using System.Text.Json;
namespace StarlightSyndicateDemo;
internal static class FittingPlannerTests
{
 public static void Run(){int n=0;void Check(bool ok,string message){if(!ok)throw new Exception("FIT35 FAIL: "+message);n++;}string State(DemoWorld w)=>JsonSerializer.Serialize(new{w.Player,w.CargoItems,w.StationItems,w.Credits,w.Day,w.DefenseStorage,w.MobilityStorage},FittingDesignStore.Json);
 foreach(var h in FleetCatalog.All){var s=new Ship();s.ApplyFleetHull(h,true);var sim=new FittingSimulation(s);Check(sim.World.Player.CombatHull==h.Id,"all hulls available in simulation / "+h.Name);var d=FittingDesign.Capture(sim.World.Player,h.Name+" test","round trip");var round=FittingDesignStore.Import(FittingDesignStore.Export(d));Check(round.Ship.CombatHull==h.Id&&round.Name==d.Name,"design identity round trip");Check(round.Ship.Attributes.SequenceEqual(s.Attributes),"attributes survive JSON / "+h.Name);Check(FittingLayoutModel.Installed(round.Ship).Count==FittingLayoutModel.Installed(s).Count,"modules survive JSON");if(!h.Playable){bool blocked=false;try{new Ship().ApplyFleetHull(h);}catch(InvalidOperationException){blocked=true;}Check(blocked,"reference simulation does not unlock campaign hull");}}
 var live=new DemoWorld();live.NewGame(0);live.Credits=1000000;live.Screen=ViewMode.Station;live.SystemId=ShipBatch21.ById[FleetCatalog.Source("Kestrel").Id].HomeSystem;Check(live.BoardFleetHull(FleetCatalog.Source("Kestrel").Id),"own matching hull");foreach(var w in live.Player.Weapons){w.ReloadLeft=0;w.Active=false;}var original=State(live);var design=FittingDesign.Capture(live.Player,"Preserved launcher fit");var imported=FittingDesignStore.Import(FittingDesignStore.Export(design));Check(State(live)==original,"save/import never mutates campaign");string error=FittingDesignStore.Apply(live,imported);Check(error.Length==0,"deploy existing fit: "+error);Check(FittingLayoutModel.Installed(live.Player).Select(m=>m.Id).SequenceEqual(FittingLayoutModel.Installed(design.Ship).Select(m=>m.Id)),"deploy modules match");
 var sim2=new FittingSimulation(live.Player);var ab=MobilityCatalog.All.First(d=>d.Kind=="AB"&&d.Size==1);var spec=FittingLayoutModel.ById[ab.Id];int slot=FittingLayoutModel.Destination(sim2.World.Player,spec);Check(sim2.Fit(spec,slot),"free simulator fits propulsion");var changed=FittingDesign.Capture(sim2.World.Player,"Free design");var before=State(live);live.Hangar[ab.Id]=0;before=State(live);Check(FittingDesignStore.Apply(live,changed).Length>0,"missing stock rejected");Check(State(live)==before,"failed fit transaction preserves full campaign fitting and inventories");live.Hangar[ab.Id]=1;error=FittingDesignStore.Apply(live,changed);Check(error.Length==0,"owned stock applies design: "+error);Check(live.Player.Mobility.Any(m=>m.ModuleId==ab.Id)&&live.Hangar[ab.Id]==0,"Fit Ship consumes actual propulsion");
 var b=State(live);var different=new Ship();different.ApplyFleetHull(FleetCatalog.Source("Tristan"));Check(FittingDesignStore.Apply(live,FittingDesign.Capture(different,"wrong hull")).Length>0&&State(live)==b,"wrong hull rejected atomically");live.Screen=ViewMode.Space;b=State(live);Check(FittingDesignStore.Apply(live,changed).Length>0&&State(live)==b,"space deployment rejected atomically");live.Screen=ViewMode.Station;
 var over=new FittingSimulation(live.Player);over.World.Player.SetStat("cpuOutput",1);FittingSimulation.ClearEquipment(over.World.Player);var gun=FittingLayoutModel.Catalog.First(d=>d.Kind=="weapon"&&d.Size==1&&WeaponCatalog.Get(d.Id).UsesLauncher&&d.Cpu>1);Check(over.Fit(gun,0),"simulator permits CPU overfit planning");Check(over.World.TotalFitCpu>over.World.Player.Stat("cpuOutput"),"overfit statistics retain actual CPU budget");Check(over.World.Player.Attributes["cpuOutput"]==1,"temporary simulation budget never leaks");
 var droneSim=new FittingSimulation(different);Check(droneSim.World.LoadDrone("dr_2203",true,1),"simulation drone bay uses actual loading");var droneRound=FittingDesignStore.Import(FittingDesignStore.Export(FittingDesign.Capture(droneSim.World.Player,"Drones")));Check(droneRound.Ship.Drones.Any(d=>d.TypeId=="dr_2203"),"drone fit round trip");
 var rig=RigCatalog.All.First(d=>d.Size==1&&d.Family=="Capacitor Control Circuit");live.Hangar[rig.Id]=1;Check(live.FitRig(rig.Id,true,0),"rig confirmation fixture");var noRigs=FittingSimulation.Copy(live.Player);noRigs.Rigs=["","",""];b=State(live);Check(FittingDesignStore.Apply(live,FittingDesign.Capture(noRigs,"No rigs")).StartsWith("RIG CONFIRMATION")&&State(live)==b,"rig destruction requires explicit confirmation");
 var buyWorld=new DemoWorld();buyWorld.NewGame(0);buyWorld.Credits=1000000;buyWorld.Screen=ViewMode.Station;buyWorld.Player=FittingSimulation.Copy(different);buyWorld.EnsureWeaponMarketStock();var buySim=new FittingSimulation(buyWorld.Player);Check(buySim.World.LoadDrone("dr_2203",true,3),"purchase simulation drones");buyWorld.Hangar["dr_2203"]=0;var quote=FittingPurchases.Plan(buyWorld,buySim.World.Player);Check(quote.Any(p=>p.Id=="dr_2203"&&p.Quantity==3),"multi-buy calculates missing drone count");float money=buyWorld.Credits;error=FittingPurchases.Buy(buyWorld,buySim.World.Player);Check(error.Length==0&&buyWorld.ItemCount("dr_2203",true)>=3&&buyWorld.Credits<money,"multi-buy executes real market orders: "+error);buyWorld.Credits=0;buyWorld.Hangar["dr_2203"]=0;b=State(buyWorld);Check(FittingPurchases.Buy(buyWorld,buySim.World.Player).Length>0&&State(buyWorld)==b,"failed multi-buy is atomic");
 var textFit=FittingTextFormat.Import(FittingTextFormat.Export(imported));Check(textFit.Ship.CombatHull==imported.Ship.CombatHull&&FittingLayoutModel.Installed(textFit.Ship).Count==FittingLayoutModel.Installed(imported.Ship).Count,"plain fitting text round trip");
 var offline=FittingDesign.Capture(live.Player,"Offline propulsion");foreach(var m in offline.Ship.Mobility.Where(m=>m.Definition!=null))m.Online=false;error=FittingDesignStore.Apply(live,offline);Check(error.Length==0&&live.Player.Mobility.Where(m=>m.Definition!=null).All(m=>!m.Online),"saved offline states deploy through a checked transaction: "+error);
 var extraRig=RigCatalog.All.First(d=>d.Size==1&&d.Family=="Trimark Armor Pump");var rigDesign=FittingDesign.Capture(live.Player,"Retain existing rig");rigDesign.Ship.Rigs[1]=extraRig.Id;live.Hangar[extraRig.Id]=1;error=FittingDesignStore.Apply(live,rigDesign);Check(error.Length==0&&live.Player.Rigs[0]==rig.Id&&live.Player.Rigs[1]==extraRig.Id,"adding a rig retains unchanged installed rigs: "+error);Check(live.ItemCount(extraRig.Id,true)==0,"adding rig consumes actual stock");
 var strat=new DemoWorld();strat.NewGame(0);strat.Screen=ViewMode.Station;strat.Player=new Ship();strat.Player.ApplyFleetHull(FleetCatalog.Source("Tengu"));strat.CargoItems.Clear();var alt=ShipBatch28.For(strat.Player.CombatHull,ShipBatch28.Categories[0]).First(x=>x.Id!=strat.Player.StrategicSubsystems[ShipBatch28.Categories[0]]);var ss=new FittingSimulation(strat.Player);Check(ss.World.FitStrategicSubsystem(alt.Id,true),"detached subsystem planning");var sd=FittingDesign.Capture(ss.World.Player,"Subsystem design");strat.Hangar[alt.Id]=0;b=State(strat);Check(FittingDesignStore.Apply(strat,sd).StartsWith("Missing subsystem")&&State(strat)==b,"subsystem deployment requires real stock atomically");strat.Hangar[alt.Id]=1;error=FittingDesignStore.Apply(strat,sd);Check(error.Length==0&&strat.Player.StrategicSubsystems[alt.Category]==alt.Id&&strat.Hangar[alt.Id]==0,"subsystem deployment consumes owned part: "+error);
 var stored=FittingDesignStore.Load();stored.Add(changed);FittingDesignStore.Save(stored);var loaded=FittingDesignStore.Load();Check(loaded.Any(d=>d.Id==changed.Id&&d.Name==changed.Name),"named design persists to disk");Console.WriteLine($"{n} fitting planner checks passed; {FleetCatalog.All.Length} hulls simulated, saved and imported.");}
}
